(function(){
  function hexToRgb(hex){
    var h = hex.replace('#','');
    return [parseInt(h.substr(0,2),16), parseInt(h.substr(2,2),16), parseInt(h.substr(4,2),16)];
  }
  var berryRgb = hexToRgb(PALETTE[0]);
  var fogRgb = hexToRgb(PALETTE[1]);
  var warmRgb = hexToRgb(PALETTE[2]);
  function rgba(rgb,a){ return 'rgba('+rgb[0]+','+rgb[1]+','+rgb[2]+','+a+')'; }

  var fogBlobs = [], branches = [], particles = [];
  var inited = false, lastSpawn = 0;

  function initScene(){
    var w = W(), h = H();
    var cx = w/2, cy = h/2;
    var minDim = Math.min(w,h);

    fogBlobs = [];
    var fogCount = 20;
    for(var i=0;i<fogCount;i++){
      var angle = Math.random()*Math.PI*2;
      var distF = 0.5 + Math.random()*0.5;
      fogBlobs.push({
        x: cx + Math.cos(angle)*distF*minDim*0.55,
        y: cy + Math.sin(angle)*distF*minDim*0.55,
        r: minDim*(0.08+Math.random()*0.14),
        phase: Math.random()*Math.PI*2,
        speed: 0.15+Math.random()*0.2,
        baseAlpha: DARK ? (0.10+Math.random()*0.12) : (0.14+Math.random()*0.16)
      });
    }

    branches = [];
    var corners = [ {ang: -0.75, dist: 0.62}, {ang: 2.4, dist: 0.62} ];
    corners.forEach(function(c, idx){
      var bx = cx + Math.cos(c.ang)*c.dist*minDim*0.5;
      var by = cy + Math.sin(c.ang)*c.dist*minDim*0.5;
      var tipDist = c.dist*0.62;
      var tx = cx + Math.cos(c.ang)*tipDist*minDim*0.5;
      var ty = cy + Math.sin(c.ang)*tipDist*minDim*0.5;
      var berries = [];
      var count = 7+Math.floor(Math.random()*3);
      for(var i=0;i<count;i++){
        var a = Math.random()*Math.PI*2;
        var rr = Math.random()*minDim*0.035;
        berries.push({
          ox: Math.cos(a)*rr,
          oy: Math.sin(a)*rr,
          r: minDim*(0.010+Math.random()*0.009),
          phase: Math.random()*Math.PI*2,
          speed: 0.6+Math.random()*0.6
        });
      }
      branches.push({bx:bx, by:by, tx:tx, ty:ty, berries:berries, swayPhase: Math.random()*Math.PI*2, swaySpeed: 0.25+idx*0.05});
    });

    particles = [];
    inited = true;
  }

  function spawnParticle(){
    var w = W(), h = H();
    var cx=w/2, cy=h/2;
    if(branches.length===0) return;
    var b = branches[Math.floor(Math.random()*branches.length)];
    var angle = Math.atan2(b.ty-cy, b.tx-cx) + (Math.random()-0.5)*1.2;
    particles.push({
      x: b.tx + (Math.random()-0.5)*20,
      y: b.ty + (Math.random()-0.5)*20,
      vx: Math.cos(angle)*(6+Math.random()*10),
      vy: Math.sin(angle)*(6+Math.random()*10) - 8,
      life: 0,
      maxLife: 3+Math.random()*2.5,
      r: 1.2+Math.random()*2.2
    });
  }

  function draw(t){
    var w = W(), h = H();
    if(!inited) initScene();

    ctx.clearRect(0,0,w,h);

    fogBlobs.forEach(function(f){
      var pulse = 0.7+0.3*Math.sin(t*f.speed+f.phase);
      var alpha = f.baseAlpha*pulse;
      var r = f.r*(0.85+0.15*pulse);
      var grad = ctx.createRadialGradient(f.x,f.y,0,f.x,f.y,r);
      grad.addColorStop(0, rgba(fogRgb, alpha));
      grad.addColorStop(1, rgba(fogRgb, 0));
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(f.x,f.y,r,0,Math.PI*2);
      ctx.fill();
    });

    if(t - lastSpawn > 0.12){
      lastSpawn = t;
      if(particles.length < 140) spawnParticle();
    }

    particles = particles.filter(function(p){ return p.life < p.maxLife; });
    particles.forEach(function(p){
      p.life += 1/60;
      p.x += p.vx/60;
      p.y += p.vy/60;
      p.vy -= 2/60;
      var lifeRatio = p.life/p.maxLife;
      var alpha = Math.sin(lifeRatio*Math.PI)*0.55;
      ctx.beginPath();
      ctx.fillStyle = rgba(warmRgb, alpha);
      ctx.shadowColor = rgba(warmRgb, alpha*0.8);
      ctx.shadowBlur = 8;
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
    });
    ctx.shadowBlur = 0;

    branches.forEach(function(b){
      var sway = Math.sin(t*b.swaySpeed+b.swayPhase)*0.05;
      ctx.save();
      ctx.translate(b.tx, b.ty);
      ctx.rotate(sway);
      ctx.translate(-b.tx, -b.ty);

      ctx.strokeStyle = rgba(fogRgb, 0.35);
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(b.bx, b.by);
      var mx = (b.bx+b.tx)/2 + (b.by-b.ty)*0.15;
      var my = (b.by+b.ty)/2 + (b.tx-b.bx)*0.15;
      ctx.quadraticCurveTo(mx,my,b.tx,b.ty);
      ctx.stroke();

      b.berries.forEach(function(br){
        var pulse = 0.75+0.25*Math.sin(t*br.speed+br.phase);
        var bx = b.tx+br.ox;
        var by = b.ty+br.oy;
        var r = br.r*pulse;
        var grad = ctx.createRadialGradient(bx-r*0.3, by-r*0.3, 0, bx, by, r);
        grad.addColorStop(0, rgba([Math.min(255,berryRgb[0]+60),Math.min(255,berryRgb[1]+40),Math.min(255,berryRgb[2]+40)], 0.95));
        grad.addColorStop(0.6, rgba(berryRgb, 0.9));
        grad.addColorStop(1, rgba(berryRgb, 0.5));
        ctx.beginPath();
        ctx.fillStyle = grad;
        ctx.shadowColor = rgba(berryRgb, 0.6*pulse);
        ctx.shadowBlur = r*2.2;
        ctx.arc(bx,by,r,0,Math.PI*2);
        ctx.fill();
      });
      ctx.shadowBlur = 0;

      ctx.restore();
    });

    requestAnimationFrame(function(now){ draw(now/1000); });
  }

  requestAnimationFrame(function(now){ draw(now/1000); });
})();
